window.WORD_AI_EXAMPLE_CHUNK = {"entries":{"living-room":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"起居室"}],"examples":[{"sentence":"The spacious living-room was filled with natural light, which made it an ideal place for reading.","translation":"宽敞的起居室充满了自然光，这使它成为阅读的理想场所。","targetForm":"living-room","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"She arranged the furniture in the living-room to create a more welcoming atmosphere for guests.","translation":"她重新布置了起居室的家具，以便为客人营造更温馨的氛围。","targetForm":"living-room","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The living-room, which overlooked the garden, was the family's favorite gathering spot.","translation":"那间俯瞰花园的起居室是家人最喜欢的聚会场所。","targetForm":"living-room","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"After the renovation, the living-room featured a modern fireplace that became the focal point of the house.","translation":"翻新后，起居室设有一个现代壁炉，成为房子的焦点。","targetForm":"living-room","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"He spent the entire evening in the living-room, engrossed in a novel that he had recently purchased.","translation":"他整个晚上都待在起居室里，全神贯注地读着一本最近买的小说。","targetForm":"living-room","senseId":"source-n-1","sourceSenseId":"n-1"}]},"list":{"senseGroups":[{"id":"source-n-6","partOfSpeech":"n.","sourceSenseIds":["n-6"],"sense":"列表"}],"examples":[{"sentence":"The short list covers a lot of ground; what connects the targets is the amount of good they will do for people, the planet, and prosperity.","translation":"这份重点清单涉及到众多领域；其中的联系是能为民众、地球和繁荣带来多少好处。","targetForm":"list","senseId":"source-n-6","sourceSenseId":"n-6"},{"sentence":"Read the list we sent you and check that all the sentences sound natural to you.","translation":"请把发给你的那张单子看一下，再确认一下所有的句子都很通顺。","targetForm":"list","senseId":"source-n-6","sourceSenseId":"n-6"}]},"lick":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"舔"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"少许"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"舔"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"卷过"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"轻轻拍打"}],"examples":[{"sentence":"The child gave the melting ice cream a quick lick before it reached her hand.","translation":"冰淇淋流到手上前，孩子赶紧舔了一口。","targetForm":"lick","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A lick of paint made the old window frame look cleaner and brighter.","translation":"刷上一点油漆，旧窗框看起来就更干净、更明亮。","targetForm":"lick","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The dog licked the child's hand after she placed a treat in her palm.","translation":"孩子把零食放在掌心后，狗舔了舔她的手。","targetForm":"licked","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Flames licked the dry grass at the edge of the field before firefighters arrived.","translation":"消防员到达前，火焰卷过田边的干草。","targetForm":"licked","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Gentle waves licked the stones along the shore throughout the quiet morning.","translation":"宁静的早晨，轻浪拍打着岸边的石头。","targetForm":"licked","senseId":"source-v-4","sourceSenseId":"v-4"}]},"lion":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"狮子"}],"examples":[{"sentence":"The lion population in West Africa has declined sharply because habitat fragmentation prevents prides from maintaining viable territories.","translation":"西非的狮子数量急剧下降，因为栖息地破碎化使狮群无法维持可生存的领地。","targetForm":"lion","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Conservationists argue that protecting the lion requires not only anti-poaching measures but also community engagement to reduce human-wildlife conflict.","translation":"保护主义者认为，保护狮子不仅需要反偷猎措施，还需要社区参与以减少人类与野生动物的冲突。","targetForm":"lion","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"While the lion symbolizes courage in many cultures, its representation in literature often reflects deeper themes of power and mortality.","translation":"虽然狮子在许多文化中象征勇气，但它在文学中的表现往往反映了权力和死亡等更深层的主题。","targetForm":"lion","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the lion is often depicted as a solitary hunter, it actually relies on coordinated group tactics to bring down large prey.","translation":"尽管狮子常被描绘成独行猎手，它实际上依赖协调的群体战术来捕获大型猎物。","targetForm":"lion","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The lion, which is an apex predator, plays a crucial role in regulating herbivore populations, thereby maintaining the balance of the ecosystem.","translation":"狮子作为顶级捕食者，在调节食草动物数量方面起着关键作用，从而维持生态系统的平衡。","targetForm":"lion","senseId":"source-n-1","sourceSenseId":"n-1"}]},"liner":{"senseGroups":[{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"内衬；衬里"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"定期客轮；班轮"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"大型客轮"},{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"衬垫；防渗膜"}],"examples":[{"sentence":"Engineers installed a protective liner inside the pipeline to prevent corrosion, thereby extending the infrastructure's lifespan significantly.","translation":"工程师在管道内部安装了保护衬里以防止腐蚀，从而显着延长了基础设施的使用寿命。","targetForm":"liner","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"Because the cargo liner operates on a fixed schedule, businesses rely on it for predictable delivery of raw materials.","translation":"由于定期货轮按固定时间表运营，企业依赖它来确保原材料的可预测交付。","targetForm":"liner","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"As air travel became more affordable, the passenger liner industry declined, leaving only a few nostalgic cruise routes that cater to tourists.","translation":"随着航空旅行变得更加实惠，客运班轮行业逐渐衰落，只留下少数迎合游客的怀旧邮轮航线。","targetForm":"liner","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The ocean liner, which was once a symbol of luxury travel, has been largely replaced by faster air routes for transatlantic journeys.","translation":"远洋班轮曾是奢华旅行的象征，如今已被更快的跨大西洋航线所取代。","targetForm":"liner","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The pond liner, made of durable synthetic material, effectively prevents water from seeping into the surrounding soil, which is essential for maintaining water levels.","translation":"池塘衬垫由耐用的合成材料制成，能有效防止水渗入周围的土壤，这对维持水位至关重要。","targetForm":"liner","senseId":"source-n-5","sourceSenseId":"n-5"}]},"liquor":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"酒"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"汁"}],"examples":[{"sentence":"Because the government regulates liquor sales strictly, illegal purchases by minors are less common.","translation":"由于政府严格监管酒类销售，未成年人非法购买的情况较少。","targetForm":"liquor","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"When people consume liquor excessively, impaired judgement can increase the risk of harmful decisions.","translation":"当人们过量饮酒时，判断力受损会增加做出有害决定的风险。","targetForm":"liquor","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"If a country taxes liquor heavily, it may discourage harmful drinking while funding public services.","translation":"如果一个国家对酒类征收较高税费，可能在资助公共服务的同时减少有害饮酒。","targetForm":"liquor","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The cultural role of liquor varies across societies, where it may be ceremonial rather than casual.","translation":"酒类在不同社会中的文化角色各异，在一些地方它属于礼仪用品而非日常饮料。","targetForm":"liquor","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the cooking liquor was clear, it contained concentrated flavours extracted from the vegetables.","translation":"尽管这份烹饪汁液清澈，它仍含有从蔬菜中萃取的浓缩风味。","targetForm":"liquor","senseId":"source-n-3","sourceSenseId":"n-3"}]},"likely":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"有可能的"},{"id":"source-adv-2","partOfSpeech":"adv.","sourceSenseIds":["adv-2"],"sense":"可能"}],"examples":[{"sentence":"It is likely that the committee will request further evidence before reaching a decision.","translation":"委员会很可能会在作出决定前要求提供更多证据。","targetForm":"likely","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The most likely explanation is that the sample was stored at the wrong temperature.","translation":"最可能的解释是样本被储存在错误的温度下。","targetForm":"likely","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Her careful preparation made her a likely candidate for the research position.","translation":"她周密的准备使她很可能成为研究职位的人选。","targetForm":"likely","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The new policy will likely affect smaller firms more than large international companies.","translation":"新政策可能会比大型跨国公司更大地影响小企业。","targetForm":"likely","senseId":"source-adv-2","sourceSenseId":"adv-2"},{"sentence":"Without a clear timetable, the project is likely to lose support from local residents.","translation":"没有明确时间表，该项目很可能失去当地居民的支持。","targetForm":"likely","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"little":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"一点点"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"小的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"很少的"},{"id":"source-adv-1","partOfSpeech":"adv.","sourceSenseIds":["adv-1"],"sense":"很少"},{"id":"source-adv-3","partOfSpeech":"adv.","sourceSenseIds":["adv-3"],"sense":"完全不"}],"examples":[{"sentence":"A little patience can prevent a small disagreement from becoming a lasting conflict.","translation":"一点耐心可以防止小分歧演变成长期冲突。","targetForm":"little","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The little village depends on a single road that is often blocked by snow.","translation":"这个小村庄依赖一条常被大雪封住的道路。","targetForm":"little","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"There is little evidence that the policy will reduce costs for ordinary families.","translation":"几乎没有证据表明该政策会降低普通家庭的开支。","targetForm":"little","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The new rules did little to clarify who was responsible for the final decision.","translation":"新规定几乎没有说明谁应对最终决定负责。","targetForm":"little","senseId":"source-adv-1","sourceSenseId":"adv-1"},{"sentence":"I could little imagine how difficult the adjustment would be before moving abroad.","translation":"出国前，我几乎无法想象适应过程会如此艰难。","targetForm":"little","senseId":"source-adv-3","sourceSenseId":"adv-3"}]},"lie":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"谎言"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"位置"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"躺着"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"位于"},{"id":"source-v-5","partOfSpeech":"v.","sourceSenseIds":["v-5"],"sense":"存在"}],"examples":[{"sentence":"The lie spread quickly because nobody checked the original source before sharing it.","translation":"这条谎言迅速传播，因为没人转发前核查原始来源。","targetForm":"lie","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A visit to the site gave the planners a clearer sense of the lie of the land.","translation":"实地考察让规划人员更清楚地了解地形布局。","targetForm":"lie","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"After the long walk, he lay on the grass and watched the clouds move slowly.","translation":"长途步行后，他躺在草地上，看着云朵缓缓移动。","targetForm":"lay","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The village lies beyond the river, where the road becomes too narrow for buses.","translation":"村庄位于河对岸，那里道路窄得无法通行公交车。","targetForm":"lies","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The difficulty lies not in finding information but in judging whether it is reliable.","translation":"困难不在于寻找信息，而在于判断其是否可靠。","targetForm":"lies","senseId":"source-v-5","sourceSenseId":"v-5"}]},"librarian":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"图书馆员"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"图书管理员"}],"examples":[{"sentence":"The university librarian implemented a new digital archiving system that greatly improved access to rare manuscripts.","translation":"大学图书馆员实施了一套新的数字存档系统，极大地改善了对珍稀手稿的获取。","targetForm":"librarian","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A skilled librarian can guide researchers through vast databases, saving them countless hours of fruitless searching.","translation":"一位熟练的图书管理员可以指导研究人员使用庞大的数据库，为他们节省无数小时的无果搜索。","targetForm":"librarian","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The children's librarian organized a weekly storytelling session that fostered a love of reading among the young participants.","translation":"儿童图书馆员组织了每周一次的故事会，培养了小参与者们对阅读的热爱。","targetForm":"librarian","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"After completing her master's degree in library science, she was hired as a reference librarian at the central public library.","translation":"获得图书馆学硕士学位后，她被聘为中央公共图书馆的参考咨询馆员。","targetForm":"librarian","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The school librarian collaborated with teachers to develop a curriculum that integrated information literacy into every subject.","translation":"学校图书馆员与教师合作，开发了一套将信息素养融入各学科的课程。","targetForm":"librarian","senseId":"source-n-1","sourceSenseId":"n-1"}]},"liberate":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"解放"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"使自由"}],"examples":[{"sentence":"Although the new policy aims to liberate small businesses from excessive regulation, its long-term effects remain uncertain.","translation":"尽管新政策旨在将小企业从过度监管中解放出来，但其长期效果仍不确定。","targetForm":"liberate","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Because the therapy aims to liberate patients from chronic pain, it has significantly improved their quality of life.","translation":"由于该疗法旨在将患者从慢性疼痛中解放出来，它显着提高了他们的生活质量。","targetForm":"liberate","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The invention of the washing machine helped liberate women from hours of manual labor, thereby enabling greater workforce participation.","translation":"洗衣机的发明帮助女性从数小时的手工劳动中解放出来，从而促进了更多的劳动力参与。","targetForm":"liberate","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The scholarship program helped liberate her from financial constraints, which allowed her to pursue a doctoral degree without part-time work.","translation":"该奖学金项目帮助她摆脱了经济束缚，这使她能够攻读博士学位而无需兼职工作。","targetForm":"liberate","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"While the movement sought to liberate the nation from colonial rule, it also sparked a cultural renaissance that reshaped national identity.","translation":"尽管该运动旨在将国家从殖民统治中解放出来，但它也引发了一场文化复兴，重塑了民族认同。","targetForm":"liberate","senseId":"source-v-1","sourceSenseId":"v-1"}]},"life":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"生活"},{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"生物"},{"id":"source-n-7","partOfSpeech":"n.","sourceSenseIds":["n-7"],"sense":"一生"},{"id":"source-n-6","partOfSpeech":"n.","sourceSenseIds":["n-6"],"sense":"寿命"},{"id":"source-n-10","partOfSpeech":"n.","sourceSenseIds":["n-10"],"sense":"无期徒刑"}],"examples":[{"sentence":"Although remote work has simplified daily life for many people, it has also blurred the boundary between work and rest.","translation":"尽管远程办公让许多人的日常生活更便利，它也模糊了工作与休息的界限。","targetForm":"life","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The expedition was designed to identify forms of life that could survive beneath the ice-covered ocean.","translation":"这次考察旨在识别能够在冰层覆盖的海洋下生存的生命形式。","targetForm":"life","senseId":"source-n-5","sourceSenseId":"n-5"},{"sentence":"She devoted her life to improving rural education, even when funding was uncertain and progress seemed slow.","translation":"她毕生致力于改善农村教育，即使资金不稳定、进展看似缓慢也没有动摇。","targetForm":"life","senseId":"source-n-7","sourceSenseId":"n-7"},{"sentence":"The engineers extended the battery's service life by reducing the amount of energy lost as heat.","translation":"工程师通过减少以热量形式损失的能量，延长了电池的使用寿命。","targetForm":"life","senseId":"source-n-6","sourceSenseId":"n-6"},{"sentence":"The judge imposed life without parole after concluding that the crime had caused irreversible harm to the community.","translation":"法官认定该罪行给社区造成不可挽回的伤害后，判处被告不得假释的无期徒刑。","targetForm":"life","senseId":"source-n-10","sourceSenseId":"n-10"}]},"literally":{"senseGroups":[{"id":"source-adv-1","partOfSpeech":"adv.","sourceSenseIds":["adv-1"],"sense":"逐字地"},{"id":"source-adv-2","partOfSpeech":"adv.","sourceSenseIds":["adv-2"],"sense":"按照字面上地"},{"id":"source-adv-3","partOfSpeech":"adv.","sourceSenseIds":["adv-3"],"sense":"不夸张地"}],"examples":[{"sentence":"When translating a legal notice, the interpreter must render key terms literally rather than substitute familiar phrases.","translation":"翻译法律通知时，译者必须逐字准确处理关键术语，而不能换成熟悉的说法。","targetForm":"literally","senseId":"source-adv-1","sourceSenseId":"adv-1"},{"sentence":"Although the speaker meant the remark figuratively, one listener understood it literally and became confused.","translation":"尽管发言者是比喻地说这句话，一位听众却按字面理解而感到困惑。","targetForm":"literally","senseId":"source-adv-2","sourceSenseId":"adv-2"},{"sentence":"The runner was literally unable to continue because a sudden storm had flooded the path.","translation":"由于突如其来的暴雨淹没了道路，这名跑者确实无法继续前行。","targetForm":"literally","senseId":"source-adv-3","sourceSenseId":"adv-3"},{"sentence":"Because the room was literally silent, the audience could hear each page being turned.","translation":"因为房间确实安静无声，观众能听到每一页被翻动的声音。","targetForm":"literally","senseId":"source-adv-3","sourceSenseId":"adv-3"},{"sentence":"The guide explained that the old sign should not be read literally, since it used a local idiom.","translation":"导游解释说，这块旧标志不应按字面理解，因为它使用了当地习语。","targetForm":"literally","senseId":"source-adv-2","sourceSenseId":"adv-2"}]},"liable":{"senseGroups":[{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"应负责的"}],"examples":[{"sentence":"While all drivers are liable for traffic violations, those who cause accidents face more severe penalties.","translation":"虽然所有司机都要对交通违规负责，但造成事故的司机会面临更严厉的处罚。","targetForm":"liable","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Although the contract was signed under duress, the company is still liable for the damages caused by the breach.","translation":"尽管合同是在胁迫下签署的，但公司仍需对违约造成的损害负责。","targetForm":"liable","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Because the manufacturer failed to issue a timely recall, it is liable for any injuries resulting from the defective product.","translation":"由于制造商未能及时召回，它要对缺陷产品造成的任何伤害负责。","targetForm":"liable","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The new policy states that employers are liable for workplace harassment, which encourages them to enforce stricter codes of conduct.","translation":"新政策规定雇主应对工作场所骚扰负责，这鼓励他们执行更严格的行为准则。","targetForm":"liable","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"If a tenant damages the property beyond normal wear and tear, they are liable for the repair costs, according to the lease agreement.","translation":"根据租赁协议，如果租户对房屋的损坏超出正常磨损，他们应承担维修费用。","targetForm":"liable","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"lid":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"限制"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"盖子"}],"examples":[{"sentence":"The new regulation puts a lid on carbon emissions, which will force industries to adopt cleaner technologies.","translation":"新规定限制了碳排放，这将迫使工业采用更清洁的技术。","targetForm":"lid","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Although the jar's lid was stuck, applying hot water loosened it enough to open without damage.","translation":"尽管罐子的盖子卡住了，但用热水浇淋使其松动，足以无损打开。","targetForm":"lid","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The company placed a tight lid on expenditure to ensure that the project remained within budget.","translation":"公司严格控制开支，以确保项目保持在预算之内。","targetForm":"lid","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"When the lid of the pressure cooker is not secured properly, steam can escape and cause serious burns.","translation":"当高压锅的盖子没有正确盖好时，蒸汽会逸出并导致严重烫伤。","targetForm":"lid","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"By keeping a lid on sensitive negotiations, the diplomats prevented premature leaks that could have derailed the peace talks.","translation":"通过保密敏感的谈判，外交官们防止了可能破坏和平谈判的过早泄密。","targetForm":"lid","senseId":"source-n-2","sourceSenseId":"n-2"}]},"litre":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"升"}],"examples":[{"sentence":"The laboratory technician carefully measured one litre of distilled water for the chemical solution.","translation":"实验室技术员仔细量取了一升蒸馏水来配制化学溶液。","targetForm":"litre","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The new engine design reduces fuel consumption to just five litres per hundred kilometers on highways.","translation":"新的发动机设计将高速公路上的油耗降低到了每百公里仅五升。","targetForm":"litres","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"During the heatwave, residents were advised to drink at least two litres of water daily to avoid dehydration.","translation":"在热浪期间，建议居民每天至少饮用两升水以避免脱水。","targetForm":"litres","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The recipe requires half a litre of milk, which should be added gradually while stirring the mixture.","translation":"这个食谱需要半升牛奶，应在搅拌混合物的同时逐渐加入。","targetForm":"litre","senseId":"source-n-1","sourceSenseId":"n-1"}]},"link":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"环"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"连结物"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"链接"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"连结"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"连接起来"}],"examples":[{"sentence":"A missing link in the chain caused the machine to stop during the safety test.","translation":"链条缺少一环，导致机器在安全测试中停止运转。","targetForm":"link","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The pedestrian bridge provides an important link between the station and the hospital.","translation":"人行桥为车站和医院之间提供了重要连接。","targetForm":"link","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Please include a link to the original report so readers can check the evidence.","translation":"请附上原报告的链接，以便读者核查证据。","targetForm":"link","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The study links poor air quality to an increased risk of respiratory illness.","translation":"该研究将空气质量差与呼吸系统疾病风险增加联系起来。","targetForm":"links","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"A new railway now links the coastal city with inland farming communities.","translation":"一条新铁路现已将沿海城市与内陆农业社区连接起来。","targetForm":"links","senseId":"source-v-4","sourceSenseId":"v-4"}]},"linguistic":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"语言的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"语言学的"},{"id":"source-other-1","partOfSpeech":"计算机","sourceSenseIds":["other-1"],"sense":"计算机中的语言或语言学的","contextReviewed":true}],"examples":[{"sentence":"The school valued linguistic diversity, allowing pupils to use home languages as resources rather than treating them as obstacles.","translation":"学校重视语言多样性，允许学生把家庭语言当作资源，而非将其视为障碍。","targetForm":"linguistic","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Her linguistic analysis showed that the two speeches used similar vocabulary but framed responsibility in strikingly different ways.","translation":"她的语言学分析显示，两篇演讲使用相似词汇，却以截然不同的方式界定责任。","targetForm":"linguistic","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Because linguistic evidence changes as archives expand, the historian treated the proposed etymology as a tentative explanation.","translation":"由于语言学证据会随档案扩展而变化，历史学家将该词源解释视为暂定说法。","targetForm":"linguistic","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The software includes a linguistic model that identifies sentence boundaries before passing the text to the search system.","translation":"该软件包含一个语言模型，在把文本交给搜索系统前识别句子边界。","targetForm":"linguistic","senseId":"source-other-1","sourceSenseId":"other-1"},{"sentence":"Although they shared a language, the delegates faced linguistic misunderstandings when familiar terms carried different legal meanings.","translation":"尽管代表们使用同一种语言，熟悉术语承载不同法律含义时仍会产生语言上的误解。","targetForm":"linguistic","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"linger":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"逗留"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"消磨"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"徘徊"}],"examples":[{"sentence":"After the discussion ended, several students lingered to ask the lecturer further questions.","translation":"讨论结束后，几名学生留下来继续向讲师提问。","targetForm":"lingered","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The scent of coffee lingered in the room long after the meeting had finished.","translation":"会议结束很久后，房间里仍萦绕着咖啡香。","targetForm":"lingered","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"A sense of doubt lingered because the report offered no evidence for its central claim.","translation":"由于报告没有为核心主张提供证据，疑虑依然存在。","targetForm":"lingered","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Do not linger over minor details when the main argument still needs development.","translation":"主要论点仍需展开时，不要在琐碎细节上耗费太多时间。","targetForm":"linger","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"He lingered by the doorway, uncertain whether to interrupt the private conversation.","translation":"他在门口徘徊，不确定是否该打断那场私人谈话。","targetForm":"lingered","senseId":"source-v-3","sourceSenseId":"v-3"}]},"library":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"图书馆"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"藏书"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"库"},{"id":"source-other-1","partOfSpeech":"计算机","sourceSenseIds":["other-1"],"sense":"程序库","contextReviewed":true}],"examples":[{"sentence":"The library remained quiet during the examination period, although every desk was occupied.","translation":"考试期间图书馆依然安静，尽管每张书桌都有人使用。","targetForm":"library","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Her personal library of legal texts helped her prepare for the entrance examination.","translation":"她个人收藏的法律书籍帮助她准备入学考试。","targetForm":"library","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The university created a digital library of interviews for future researchers.","translation":"大学建立了访谈数字资料库，供未来研究人员使用。","targetForm":"library","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The developer imported a library that could process images more efficiently.","translation":"开发者导入了一个能更高效处理图像的程序库。","targetForm":"library","senseId":"source-other-1","sourceSenseId":"other-1"},{"sentence":"A well-organised library makes reliable evidence easier to find and evaluate.","translation":"组织良好的图书馆能使可靠证据更容易被找到和评估。","targetForm":"library","senseId":"source-n-1","sourceSenseId":"n-1"}]},"listen":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"听从"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"倾听"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"听"}],"examples":[{"sentence":"Don’t blame the leaders for appearing short-sighted and indecisive; the fault may lie with us, the public, for not listening to the worrywarts.","translation":"因此请不要指责政治家的短视和犹豫不决；真正有错的可能是我们，一群不愿聆听忠言的公众。","targetForm":"listening","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"If you'd listen a little more carefully to what the teacher says, you'd probably be able to understand.","translation":"假如你在老师讲课的时候再集中一点去听讲的话，你应该就能弄明白了。","targetForm":"listen","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"If we were supposed to talk more than listen, we would have been given two mouths and one ear.","translation":"如果我们应该少听多说话, 那么我们应该得到两个嘴巴一只耳朵才是。","targetForm":"listen","senseId":"source-v-1","sourceSenseId":"v-1"}]},"literature":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"文学"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"著作"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"文学；著作；广告资料；商品介绍","contextReviewed":true}],"examples":[{"sentence":"Reading literature from different periods can reveal how social values have changed.","translation":"阅读不同时期的文学作品能揭示社会价值观如何变化。","targetForm":"literature","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The medical literature contains strong evidence that early treatment improves recovery.","translation":"医学文献有力证明，早期治疗有助于康复。","targetForm":"literature","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Before prescribing the medicine, the doctor reviewed the recent clinical literature.","translation":"开药前，医生查阅了近期临床文献。","targetForm":"literature","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The company sent product literature explaining how the new device should be installed.","translation":"公司寄送了产品资料，说明新设备应如何安装。","targetForm":"literature","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"Her thesis compares modern children's literature with traditional folk tales.","translation":"她的论文比较现代儿童文学与传统民间故事。","targetForm":"literature","senseId":"source-n-1","sourceSenseId":"n-1"}]},"like":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"相似的"}],"examples":[{"sentence":"While depreciation would never be eurozone officials’ stated policy, it currently looks like all roads lead in that direction.","translation":"贬值永远不会是欧元区官员直言不讳的选择，但从目前来看，这正是欧洲在走的路。","targetForm":"like","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Or it may be that the greatest happiness of all comes from not having to worry about stuff like this.","translation":"或者，说到底，最大的幸福来自不再担心这一问题。","targetForm":"like","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"light":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"光"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"灯"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"轻的"},{"id":"source-adj-7","partOfSpeech":"adj.","sourceSenseIds":["adj-7"],"sense":"淡色的"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"照亮"}],"examples":[{"sentence":"Because natural light changes through the day, the architect placed the reading desks near the tall windows.","translation":"由于自然光会随一天的时间变化，建筑师把阅读桌放在高窗附近。","targetForm":"light","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The technician replaced a broken light in the corridor before visitors arrived for the evening lecture.","translation":"晚间讲座的访客到达前，技术员更换了走廊里坏掉的一盏灯。","targetForm":"light","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Although the suitcase was light, its reinforced frame protected the instruments during the long journey.","translation":"尽管这个手提箱很轻，它的加固框架仍在长途运输中保护了仪器。","targetForm":"light","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"She chose a light blue background so that the dark text would remain easy to read on a small screen.","translation":"她选择了浅蓝色背景，以便深色文字在小屏幕上仍清晰易读。","targetForm":"light","senseId":"source-adj-7","sourceSenseId":"adj-7"},{"sentence":"To light the outdoor stage safely, the crew tested every cable before the festival opened.","translation":"为安全照亮露天舞台，工作人员在节日开幕前测试了每一根电缆。","targetForm":"light","senseId":"source-v-2","sourceSenseId":"v-2"}]},"lift":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"昂扬"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"电梯"},{"id":"source-v-9","partOfSpeech":"v.","sourceSenseIds":["v-9"],"sense":"消散"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"提高"},{"id":"source-v-6","partOfSpeech":"v.","sourceSenseIds":["v-6"],"sense":"举起"}],"examples":[{"sentence":"The grant gave the small museum a lift by allowing it to repair the entrance and extend opening hours.","translation":"这笔拨款提振了这家小博物馆，使它得以维修入口并延长开放时间。","targetForm":"lift","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"When the lift stopped between floors, the building manager reassured the passengers and called a technician.","translation":"电梯停在楼层之间时，楼宇经理安抚乘客并叫来技术员。","targetForm":"lift","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The new scholarship lifted a financial burden from the family while the student completed her degree.","translation":"学生完成学位期间，新奖学金减轻了家庭的经济负担。","targetForm":"lifted","senseId":"source-v-9","sourceSenseId":"v-9"},{"sentence":"Although the evidence was limited, the announcement lifted public confidence in the recovery plan.","translation":"尽管证据有限，这项宣布仍提高了公众对复苏计划的信心。","targetForm":"lifted","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Before the archive reopened, staff lifted the heavy boxes carefully onto shelves designed to support their weight.","translation":"档案馆重新开放前，工作人员小心地把重箱子举到设计可承重的架子上。","targetForm":"lifted","senseId":"source-v-6","sourceSenseId":"v-6"}]},"literary":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"文学的"}],"examples":[{"sentence":"The lecture explored literary techniques that make a narrator seem unreliable.","translation":"讲座探讨了使叙述者显得不可靠的文学技巧。","targetForm":"literary","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Her literary interests extended from ancient poetry to contemporary travel writing.","translation":"她的文学兴趣从古代诗歌延伸到当代游记写作。","targetForm":"literary","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The prize recognises emerging literary talent from communities that are often overlooked.","translation":"该奖项表彰常被忽视的社区中崭露头角的文学人才。","targetForm":"literary","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The archive preserves letters of considerable literary value as well as historical importance.","translation":"这座档案馆保存了具有重要文学价值和历史意义的书信。","targetForm":"literary","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although the essay contains literary references, its central argument remains clear to general readers.","translation":"尽管文章包含文学典故，其核心论点对普通读者仍然清晰。","targetForm":"literary","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"line":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"列"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"线"},{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"线路"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"排成一行"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"加衬里"}],"examples":[{"sentence":"Students formed a line outside the hall while the examination papers were distributed.","translation":"试卷发放时，学生们在大厅外排成一列。","targetForm":"line","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A thin red line on the graph shows when the temperature began to rise.","translation":"图表上的一条细红线显示温度何时开始上升。","targetForm":"line","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The new railway line will connect several towns that currently have poor transport links.","translation":"新铁路线将连接目前交通不便的几个城镇。","targetForm":"line","senseId":"source-n-5","sourceSenseId":"n-5"},{"sentence":"Volunteers lined the street to welcome the athletes after the competition.","translation":"比赛结束后，志愿者沿街列队欢迎运动员。","targetForm":"lined","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The tailor lined the coat with warm wool before the winter season began.","translation":"冬季来临前，裁缝给大衣加了保暖羊毛衬里。","targetForm":"lined","senseId":"source-v-4","sourceSenseId":"v-4"}]},"linen":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"亚麻制品"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"亚麻布"}],"examples":[{"sentence":"When properly cared for, linen garments can last for decades, thereby reducing the need for frequent replacements.","translation":"如果保养得当，亚麻服装可以使用数十年，从而减少频繁更换的需要。","targetForm":"linen","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Although linen is more expensive than cotton, its durability and breathability make it a worthwhile investment for bedding.","translation":"尽管亚麻布比棉布更贵，但其耐用性和透气性使其成为值得投资的床上用品。","targetForm":"linen","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because linen absorbs moisture without feeling damp, it is often used for towels in high-end spas.","translation":"由于亚麻布吸湿而不感潮湿，它常被用于高端水疗中心的毛巾。","targetForm":"linen","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The designer chose pure white linen for the tablecloths, which created an elegant atmosphere at the wedding reception.","translation":"设计师为桌布选择了纯白色亚麻布，这在婚宴上营造了优雅的氛围。","targetForm":"linen","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"To ensure a crisp appearance, the hotel staff iron the linen napkins while they are still slightly damp.","translation":"为确保挺括的外观，酒店员工在亚麻餐巾还微湿时熨烫它们。","targetForm":"linen","senseId":"source-n-3","sourceSenseId":"n-3"}]},"limp":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"跛行"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"无力的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"软弱的"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"跛行"}],"examples":[{"sentence":"Her limp became more noticeable after she had walked across the uneven ground.","translation":"她走过凹凸不平的地面后，跛行变得更明显。","targetForm":"limp","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The flowers looked limp because nobody had watered them during the heatwave.","translation":"由于热浪期间无人浇水，花朵显得萎蔫无力。","targetForm":"limp","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"His limp response failed to address the strongest criticism of the proposal.","translation":"他软弱的回应未能回答对该提案最有力的批评。","targetForm":"limp","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"She limped home slowly after twisting her ankle on the wet pavement.","translation":"她在人行道湿滑处扭伤脚踝后，一瘸一拐地慢慢回家。","targetForm":"limped","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The wet cloth hung limp from the rail after the storm had passed.","translation":"暴风雨过后，湿布无力地垂在栏杆上。","targetForm":"limp","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"literacy":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"识字"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"读写能力"}],"examples":[{"sentence":"Although the country's literacy rate has improved significantly, functional illiteracy remains a barrier to economic advancement for many adults.","translation":"尽管该国的识字率已显着提高，但功能性文盲仍然是许多成年人经济进步的障碍。","targetForm":"literacy","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Media literacy education, which teaches students to critically analyze news sources, is vital in an era of widespread misinformation.","translation":"媒介素养教育教导学生批判性地分析新闻来源，在错误信息泛滥的时代至关重要。","targetForm":"literacy","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because digital literacy is now essential for accessing government services, many community centers offer free training to bridge the gap.","translation":"由于数字素养如今对于获取政府服务至关重要，许多社区中心提供免费培训以弥合差距。","targetForm":"literacy","senseId":"source-n-1","sourceSenseId":"n-1"}]},"liberty":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"自由"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"许可"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"冒失"}],"examples":[{"sentence":"Freedom of speech is a basic liberty that allows citizens to question public decisions.","translation":"言论自由是一项基本自由，使公民能够质询公共决策。","targetForm":"liberty","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The permit gave researchers the liberty to enter the archive during restricted hours.","translation":"许可证允许研究人员在受限时段进入档案馆。","targetForm":"liberty","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The author took the liberty of correcting several dates after consulting the original records.","translation":"作者查阅原始记录后，擅自更正了几个日期。","targetForm":"liberty","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The court ruled that the detention violated his liberty without sufficient legal justification.","translation":"法院裁定，该拘留在缺乏充分法律依据的情况下侵犯了他的人身自由。","targetForm":"liberty","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Residents valued the liberty to move freely between the two regions.","translation":"居民珍视在两个地区之间自由往来的权利。","targetForm":"liberty","senseId":"source-n-1","sourceSenseId":"n-1"}]},"live":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"活的"},{"id":"source-adj-4","partOfSpeech":"adj.","sourceSenseIds":["adj-4"],"sense":"实况转播的"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"居住"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"生存"},{"id":"source-adv-1","partOfSpeech":"adv.","sourceSenseIds":["adv-1"],"sense":"实况地"}],"examples":[{"sentence":"The researchers released the live animals only after confirming that their habitat was safe.","translation":"研究人员确认栖息地安全后才放归活体动物。","targetForm":"live","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The live broadcast began late because the storm damaged a communications cable.","translation":"暴风雨损坏通信电缆后，实况转播延迟开始。","targetForm":"live","senseId":"source-adj-4","sourceSenseId":"adj-4"},{"sentence":"She has lived in three countries and learned to adapt to unfamiliar routines.","translation":"她曾在三个国家生活，并学会适应陌生的日常安排。","targetForm":"lived","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Few students can live on a part-time wage without careful financial planning.","translation":"没有周密的财务规划，很少有学生能仅靠兼职工资生活。","targetForm":"live","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The reporter spoke live from the station as passengers waited for further instructions.","translation":"乘客等待进一步指示时，记者从车站进行现场报道。","targetForm":"live","senseId":"source-adv-1","sourceSenseId":"adv-1"}]},"limit":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"限度"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"极限"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"限制"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"限定"}],"examples":[{"sentence":"The budget sets a clear limit on how much the department can spend this year.","translation":"预算明确限定了该部门今年的支出额度。","targetForm":"limit","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Every material has a limit beyond which further pressure will cause permanent damage.","translation":"每种材料都有一个极限，超过后继续施压会造成永久损坏。","targetForm":"limit","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The new rules limit the amount of personal data that companies may collect.","translation":"新规限制公司可收集的个人数据量。","targetForm":"limit","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The author limited the introduction to essential background information and defined the research question early.","translation":"作者将引言限于必要的背景信息，并及早界定研究问题。","targetForm":"limited","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Knowing your limits can prevent a demanding schedule from becoming harmful to your health.","translation":"了解自己的限度能防止繁重日程损害健康。","targetForm":"limits","senseId":"source-n-3","sourceSenseId":"n-3"}]},"lifetime":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"终生"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"一生"}],"examples":[{"sentence":"Each of you must work hard for a lifetime, and only then will you be able to maintain a relationship.","translation":"彼此必须一辈子努力,才能把感情维系好。","targetForm":"lifetime","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Tatoeba: We've got more sentences than your mom could ever say in her lifetime.","translation":"Tatoeba:我们有的句子比你妈这辈子说的都多。","targetForm":"lifetime","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Some things I will never be able to learn in my lifetime.","translation":"有些东西是我永远也学不会的。","targetForm":"lifetime","senseId":"source-n-1","sourceSenseId":"n-1"}]},"lively":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"活泼的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"生动的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"鲜明的"}],"examples":[{"sentence":"The class became lively when students were asked to defend opposing viewpoints.","translation":"当学生被要求为相反观点辩护时，课堂变得活跃起来。","targetForm":"lively","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Her lively description helped readers imagine the crowded market clearly.","translation":"她生动的描述帮助读者清晰想象拥挤的市场。","targetForm":"lively","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"The town has a lively arts scene despite its small population.","translation":"尽管人口不多，这座小镇的艺术氛围很活跃。","targetForm":"lively","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"A lively exchange of ideas often produces better questions as well as better answers.","translation":"热烈的思想交流常能带来更好的问题和答案。","targetForm":"lively","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The exhibition uses lively colours to draw attention to the issue of water scarcity.","translation":"展览用鲜明色彩引起人们对水资源短缺问题的关注。","targetForm":"lively","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"limitation":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"缺陷"}],"examples":[{"sentence":"Gestural language had, however, serious limitations, since it could not be used in the dark or at distance.","translation":"可是，手语也绝对不是万能的，当四周太暗，或者距离太远的时候，它就完全派不上用场。","targetForm":"limitations","senseId":"source-n-2","sourceSenseId":"n-2"}]},"liver":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"肝脏"}],"examples":[{"sentence":"I have a corner in my liver just for you, alcohol.","translation":"我在肝里给你留了个地方，酒精啊。","targetForm":"liver","senseId":"source-n-1","sourceSenseId":"n-1"}]},"litter":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"垃圾"}],"examples":[{"sentence":"A lot of people climb the railing, and even litter.","translation":"很多人跳过栏杆，还丢垃圾。","targetForm":"litter","senseId":"source-n-1","sourceSenseId":"n-1"}]},"lip":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"唇"}],"examples":[{"sentence":"From that day forth he merely tasted his food, and only just moistened his lips with drink.","translation":"从那时开始他就只是尝一尝他的食物，也仅仅只是用饮料润湿了嘴唇而已。","targetForm":"lips","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Gorillas cannot use their lips and tongues to speak, but they can communicate with people in other ways.","translation":"虽然猩猩不懂得开口说话，但牠们能用其他方式和人类沟通。","targetForm":"lips","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Throughout the five years of painful cancer treatments, he managed to keep a stiff upper lip.","translation":"这五年痛苦的癌症治疗他终于坚持下来了。","targetForm":"lip","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"He raised the glass to his lips and drained it at one gulp.","translation":"他把杯子举到嘴边，一饮而尽。","targetForm":"lips","senseId":"source-n-1","sourceSenseId":"n-1"}]},"license":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"执照"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"许可证"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"特许"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"许可"}],"examples":[{"sentence":"The clinic renewed its license after meeting the new safety requirements.","translation":"该诊所在满足新的安全要求后续签了执照。","targetForm":"license","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The museum obtained a license to reproduce the photographs in its exhibition guide.","translation":"博物馆获得许可，可在展览指南中复制这些照片。","targetForm":"license","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The agency licensed the design for educational use while retaining the artist's copyright.","translation":"该机构许可将设计用于教育用途，同时保留艺术家的版权。","targetForm":"licensed","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The software is licensed to schools that agree to protect student data.","translation":"该软件授权给同意保护学生数据的学校使用。","targetForm":"licensed","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"A fishing license is required before visitors may enter the protected lake.","translation":"游客进入受保护湖区前必须持有钓鱼许可证。","targetForm":"license","senseId":"source-n-2","sourceSenseId":"n-2"}]},"likewise":{"senseGroups":[{"id":"source-adv-2","partOfSpeech":"adv.","sourceSenseIds":["adv-2"],"sense":"也"},{"id":"source-adv-1","partOfSpeech":"adv.","sourceSenseIds":["adv-1"],"sense":"同样地"}],"examples":[{"sentence":"Several participants praised the flexible timetable; the tutors likewise valued the extra time for feedback.","translation":"一些参与者称赞灵活的时间表，导师们也重视额外的反馈时间。","targetForm":"likewise","senseId":"source-adv-2","sourceSenseId":"adv-2"},{"sentence":"The report recommends cheaper public transport and likewise calls for safer cycling routes.","translation":"报告建议降低公共交通费用，也呼吁建设更安全的自行车路线。","targetForm":"likewise","senseId":"source-adv-2","sourceSenseId":"adv-2"},{"sentence":"Her supervisor had faced a similar setback and likewise understood why she needed more time.","translation":"她的导师曾遭遇类似挫折，因此也理解她为何需要更多时间。","targetForm":"likewise","senseId":"source-adv-2","sourceSenseId":"adv-2"},{"sentence":"Good evidence must be relevant; likewise, it must come from a trustworthy source.","translation":"好的证据必须相关，同样也必须来自可信来源。","targetForm":"likewise","senseId":"source-adv-1","sourceSenseId":"adv-1"},{"sentence":"Plants require light to grow, and young animals likewise depend on a stable environment.","translation":"植物生长需要光照，幼小动物同样依赖稳定的环境。","targetForm":"likewise","senseId":"source-adv-1","sourceSenseId":"adv-1"}]},"likelihood":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"可能性"}],"examples":[{"sentence":"Furthermore, a degraded macroeconomic and financial environment increases the likelihood of bank failures, with immediate consequences for public finances and economic confidence.","translation":"此外，一个恶化的宏观经济和金融环境增加了银行破产的可能性，也将迅速影响公共财政状况和市场信心。","targetForm":"likelihood","senseId":"source-n-2","sourceSenseId":"n-2"}]}}};
